class Solution {
public:
    string predictPartyVictory(string senate) {
        queue<int> rQueue, dQueue;
        int n = senate.size();
        for (int i = 0; i < n; ++i) {
            if (senate[i] == 'R') rQueue.push(i);
            else dQueue.push(i);
        }
        while (!rQueue.empty() && !dQueue.empty()) {
            int rIdx = rQueue.front(); rQueue.pop();
            int dIdx = dQueue.front(); dQueue.pop();
            if (rIdx < dIdx) rQueue.push(rIdx + n);
            else dQueue.push(dIdx + n);
        }
        return rQueue.empty() ? "Dire" : "Radiant";
    }
};

class Solution {
    public String predictPartyVictory(String senate) {
        Queue<Integer> rQueue = new ArrayDeque<>();
        Queue<Integer> dQueue = new ArrayDeque<>();
        int n = senate.length();
        for (int i = 0; i < n; i++) {
            if (senate.charAt(i) == 'R') rQueue.offer(i);
            else dQueue.offer(i);
        }
        while (!rQueue.isEmpty() && !dQueue.isEmpty()) {
            int rIdx = rQueue.poll();
            int dIdx = dQueue.poll();
            if (rIdx < dIdx) rQueue.offer(rIdx + n);
            else dQueue.offer(dIdx + n);
        }
        return rQueue.isEmpty() ? "Dire" : "Radiant";
    }
}

