var predictPartyVictory = function(senate) {
    const rQueue = [];
    const dQueue = [];
    const n = senate.length;
    for (let i = 0; i < n; i++) {
        if (senate[i] === 'R') rQueue.push(i);
        else dQueue.push(i);
    }
    let rHead = 0, dHead = 0;
    while (rHead < rQueue.length && dHead < dQueue.length) {
        const rIdx = rQueue[rHead++];
        const dIdx = dQueue[dHead++];
        if (rIdx < dIdx) rQueue.push(rIdx + n);
        else dQueue.push(dIdx + n);
    }
    return rHead < rQueue.length ? "Radiant" : "Dire";
};
